// Re-encodes PNG screenshots as WebP through headless Chrome (no extra dependencies): the repository keeps a small set of WebP files,
// and the full PNG sets are regenerated by battle-shots.mjs / app-smoke.mjs when needed.
// node scripts/shots-to-webp.mjs <out-dir> [--quality 0.82] <file.png>...   (output: <out-dir>/<name>.webp)
import { spawn } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { basename, join, resolve } from 'node:path'
import { tmpdir } from 'node:os'

const args = process.argv.slice(2)
const qualityAt = args.indexOf('--quality')
const quality = qualityAt < 0 ? 0.82 : Number(args.splice(qualityAt, 2)[1])
const [outDir, ...files] = args
if (!outDir || !files.length) throw new Error('usage: shots-to-webp.mjs <out-dir> [--quality q] <png>...')
const chrome = ['C:/Program Files/Google/Chrome/Application/chrome.exe', 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'].find(existsSync)
if (!chrome) throw new Error('Chrome or Edge not found')
mkdirSync(resolve(outDir), { recursive: true })
const sleep = ms => new Promise(done => setTimeout(done, ms))
const port = 9335
const proc = spawn(chrome, [`--remote-debugging-port=${port}`, `--user-data-dir=${join(tmpdir(), 'spellwhim-webp-' + Date.now())}`, '--headless=new', '--disable-gpu', 'about:blank'], { stdio: 'ignore' })
let target
for (let i = 0; i < 50 && !target; i++) {
  await sleep(200)
  try { target = (await (await fetch(`http://127.0.0.1:${port}/json`)).json()).find(item => item.type === 'page') } catch { /* not up yet */ }
}
if (!target) throw new Error('DevTools did not start')
const socket = new WebSocket(target.webSocketDebuggerUrl)
await new Promise(done => socket.addEventListener('open', done))
let nextId = 1
const waiting = new Map()
socket.addEventListener('message', event => { const message = JSON.parse(event.data); if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) } })
const send = (method, params = {}) => new Promise(done => { const id = nextId++; waiting.set(id, done); socket.send(JSON.stringify({ id, method, params })) })
let total = 0
for (const file of files) {
  const data = readFileSync(file).toString('base64')
  const expression = `new Promise((done, fail) => { const img = new Image(); img.onload = () => { const c = document.createElement('canvas'); c.width = img.naturalWidth; c.height = img.naturalHeight; c.getContext('2d').drawImage(img, 0, 0); c.toBlob(blob => { const r = new FileReader(); r.onload = () => done(String(r.result).split(',')[1]); r.readAsDataURL(blob) }, 'image/webp', ${quality}) }; img.onerror = () => fail('decode'); img.src = 'data:image/png;base64,${data}' })`
  const { result } = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })
  const bytes = Buffer.from(result.result.value, 'base64')
  const out = join(resolve(outDir), basename(file, '.png') + '.webp')
  writeFileSync(out, bytes)
  total += bytes.length
  console.log('wrote', out, Math.round(bytes.length / 1024) + ' KB')
}
console.log('total', (total / 1048576).toFixed(2), 'MB')
socket.close(); proc.kill()
